def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp = [h[1] for h in history]
    my = [h[0] for h in history]
    opp_def = sum(1 for x in opp if x == 'D')

    if opp_def == n and n >= 6:
        return 'D'

    if opp_def == 0:
        if n < 5:
            return 'C'
        if n == 5:
            return 'D'
        if n == 6:
            return 'C'
        if n == 7:
            return 'C'
        return 'D'

    if opp_def == 1:
        return 'C'

    last_me = my[-1]
    last_opp = opp[-1]

    if last_me == 'D' and last_opp == 'C':
        return 'D'

    if last_me == 'C' and last_opp == 'D':
        if n >= 4 and my[-2] == 'D' and opp[-2] == 'D' and my[-3] == 'D' and opp[-3] == 'D':
            return 'C'
        return 'D'

    if last_me == 'D' and last_opp == 'D':
        dd = 0
        for i in range(n-1, -1, -1):
            if my[i] == 'D' and opp[i] == 'D':
                dd += 1
            else:
                break
        if dd >= 3:
            return 'C'
        return 'D'

    return 'C'
